css:
.slip-qr {
    padding-top: 4px;
}

.judul {
    letter-spacing: 2px;
    margin-bottom: 2px;
}

.nomor {
    margin-top: 0;
    text-decoration: underline;
}

.content tr td {
    padding-bottom: 0 !important;
    vertical-align: top;
}

.content tr td:nth-child(1) {
    padding-left: 0 !important;
}

.kotak-qr {
    border: 1px solid #000;
    margin-top: 12px;
    padding: 12px 8px;
}

.gambar-qr {
    width: 190px;
    height: 190px;
}

.masa-berlaku {
    font-weight: bold;
    margin-top: 6px;
}

.catatan {
    font-size: 11px;
    margin-top: 4px;
}
